import sys, os, math
sys.path.insert(0,'/home/claude/lengua')
import svgs as S
from svgs import svg, sun, cloud, tree, text, SKY, BLUE, ORANGE, GREEN, DGREEN, BROWN, DBROWN, YEL, GREY, DGREY, WHITE, RED, SAND, WATER, INK, PINK
S.OUT='/home/claude/subjects/en/img'; os.makedirs(S.OUT,exist_ok=True)
PURPLE='#7D3C98'; SKIN='#F5CBA7'; LGREEN='#A9DFBF'; LBLUE='#AED6F1'; LGREY='#D5D8DC'; GOLD='#D4AC0D'; CREAM='#FFF4D6'; LAV='#F3F0FA'
def box(x,y,w,h,c,t='',sz=16,tc=WHITE,r=8): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'+(text(x+w/2,y+h/2+sz*0.36,t,sz,tc) if t else '')
def bubble(x,y,w,h,t,sz=12,c=WHITE,stroke=BLUE,tc=INK,tail='l'):
    tl = f'<path d="M{x+20} {y+h} l-8 14 l22 -14 Z" fill="{c}" stroke="{stroke}" stroke-width="2"/>' if tail=='l' else f'<path d="M{x+w-20} {y+h} l8 14 l-22 -14 Z" fill="{c}" stroke="{stroke}" stroke-width="2"/>'
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="10" fill="{c}" stroke="{stroke}" stroke-width="2"/>{tl}{text(x+w/2,y+h/2+sz*0.36,t,sz,tc)}'
def person(x,y,s=1,shirt=BLUE,hair=BROWN,style='short',beard=False,glasses=False,old=False):
    hc = GREY if old else hair
    if style=='curly': h=f'<circle cx="-10" cy="-40" r="7" fill="{hc}"/><circle cx="0" cy="-45" r="8" fill="{hc}"/><circle cx="10" cy="-40" r="7" fill="{hc}"/><circle cx="-14" cy="-30" r="5" fill="{hc}"/><circle cx="14" cy="-30" r="5" fill="{hc}"/>'
    elif style=='long': h=f'<path d="M-16 -32 q0 -24 16 -24 q16 0 16 24 v22 h-6 v-18 q-10 -6 -20 0 v18 h-6 Z" fill="{hc}"/>'
    elif style=='bald': h=''
    else: h=f'<path d="M-15 -34 q15 -22 30 0 Z" fill="{hc}"/>'
    b = f'<path d="M-12 -24 q12 14 24 0 v8 q-12 10 -24 0 Z" fill="{hc}"/>' if beard else ''
    g = f'<circle cx="-6" cy="-33" r="5" fill="none" stroke="{INK}" stroke-width="1.5"/><circle cx="6" cy="-33" r="5" fill="none" stroke="{INK}" stroke-width="1.5"/>' if glasses else ''
    return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="-30" r="15" fill="{SKIN}"/>{h}<circle cx="-5" cy="-33" r="2" fill="#000"/><circle cx="5" cy="-33" r="2" fill="#000"/><path d="M-6 -24 q6 6 12 0" stroke="#000" stroke-width="2" fill="none"/>{b}{g}<rect x="-14" y="-14" width="28" height="36" rx="8" fill="{shirt}"/><rect x="-12" y="22" width="9" height="24" fill="{DGREY}"/><rect x="3" y="22" width="9" height="24" fill="{DGREY}"/><rect x="-24" y="-10" width="9" height="26" rx="4" fill="{SKIN}"/><rect x="15" y="-10" width="9" height="26" rx="4" fill="{SKIN}"/></g>'
def dog(x,y,s=1,c=WHITE):
    spots=''.join(f'<circle cx="{a}" cy="{b}" r="4" fill="#000"/>' for a,b in ((-18,-4),(-4,6),(10,-2),(30,-18)))
    return f'<g transform="translate({x} {y}) scale({s})"><rect x="-30" y="-10" width="56" height="30" rx="12" fill="{c}" stroke="{LGREY}"/><circle cx="30" cy="-14" r="16" fill="{c}" stroke="{LGREY}"/><ellipse cx="20" cy="-24" rx="6" ry="12" fill="#000"/><circle cx="36" cy="-16" r="2.5" fill="#000"/><circle cx="44" cy="-8" r="4" fill="#000"/>{spots}<rect x="-26" y="18" width="8" height="18" fill="{c}"/><rect x="-8" y="18" width="8" height="18" fill="{c}"/><rect x="8" y="18" width="8" height="18" fill="{c}"/><path d="M-30 -6 q-14 -14 -10 -26" stroke="{c}" stroke-width="6" fill="none"/></g>'
def house(x,y,s=1,c=SAND,roof=RED,floors=2):
    win=''.join(f'<rect x="{xx}" y="{yy}" width="12" height="12" fill="{WATER}"/>' for xx in (-24,12) for yy in range(-26,-26+floors*22,22))
    return f'<g transform="translate({x} {y}) scale({s})"><rect x="-34" y="-30" width="68" height="{30+floors*10}" fill="{c}"/><polygon points="-40,-30 0,-62 40,-30" fill="{roof}"/>{win}<rect x="-8" y="{floors*10-6}" width="16" height="36" fill="{DBROWN}"/></g>'
def building(x,y,w,h,c=GREY,win=LBLUE): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>'+''.join(f'<rect x="{x+6+i*14}" y="{y+8+j*16}" width="8" height="10" fill="{win}"/>' for i in range(int((w-6)//14)) for j in range(int((h-8)//16)))
def kite(x,y,s=1,c=RED): return f'<g transform="translate({x} {y}) scale({s})"><polygon points="0,-24 16,0 0,24 -16,0" fill="{c}"/><line x1="0" y1="-24" x2="0" y2="24" stroke="{INK}" stroke-width="1"/><line x1="-16" y1="0" x2="16" y2="0" stroke="{INK}" stroke-width="1"/><path d="M0 24 q-10 20 -4 40" stroke="{INK}" stroke-width="1.5" fill="none"/></g>'
def bike(x,y,s=1,c=PURPLE): return f'<g transform="translate({x} {y}) scale({s})"><circle cx="-22" cy="0" r="16" fill="none" stroke="{INK}" stroke-width="3"/><circle cx="22" cy="0" r="16" fill="none" stroke="{INK}" stroke-width="3"/><path d="M-22 0 L-8 -20 L14 -20 L22 0 L0 0 Z" fill="none" stroke="{c}" stroke-width="3"/><line x1="-8" y1="-20" x2="-12" y2="-28" stroke="{c}" stroke-width="3"/><line x1="14" y1="-20" x2="18" y2="-28" stroke="{c}" stroke-width="3"/></g>'
def stairs(x,y,n=5,st=14,c=BROWN): return ''.join(f'<rect x="{x+i*st}" y="{y-(i+1)*st}" width="{st}" height="{(i+1)*st}" fill="{c}" stroke="{DBROWN}"/>' for i in range(n))
def lift(x,y,w=40,h=60): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{LGREY}" stroke="{DGREY}" stroke-width="2"/><line x1="{x+w/2}" y1="{y}" x2="{x+w/2}" y2="{y+h}" stroke="{DGREY}" stroke-width="2"/><polygon points="{x+w/2-6},{y-8} {x+w/2},{y-16} {x+w/2+6},{y-8}" fill="{DGREY}"/><polygon points="{x+w/2-6},{y+h+8} {x+w/2},{y+h+16} {x+w/2+6},{y+h+8}" fill="{DGREY}"/>'
def num(x,y,n,c=BLUE,r=18): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}"/>{text(x,y+6,str(n),15,WHITE)}'
def sheep(x,y,s=1): return S.sheep(x,y,s)
def bee(x,y,s=1): return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="-6" cy="-16" rx="12" ry="8" fill="{LBLUE}" opacity=".8"/><ellipse cx="8" cy="-16" rx="12" ry="8" fill="{LBLUE}" opacity=".8"/><ellipse cx="0" cy="0" rx="24" ry="14" fill="{YEL}"/><rect x="-10" y="-14" width="7" height="28" fill="#000"/><rect x="4" y="-14" width="7" height="28" fill="#000"/><circle cx="24" cy="-2" r="9" fill="#000"/><circle cx="27" cy="-5" r="2" fill="{WHITE}"/></g>'
def star(x,y,r=12,c=YEL):
    pts=' '.join(f'{x+(r if i%2==0 else r*0.45)*math.cos(math.pi/2*-1+i*math.pi/5):.1f},{y+(r if i%2==0 else r*0.45)*math.sin(-math.pi/2+i*math.pi/5):.1f}' for i in range(10))
    return f'<polygon points="{pts}" fill="{c}"/>'

